/* Endfield-inspired learning UI. Reference: hhikr/endfield-ui-skill.
 * This layer changes presentation only; course IDs, gates and saved data stay in the existing engines. */
const efPageNames={hub:'LEARNING ROOM',subject:'COURSE PATH',books:'READING ROOM',reader:'READING',account:'PERSONAL ACCOUNT',guide:'LEARNING GUIDE',glossary:'ILLUSTRATED GLOSSARY',incident:'TROUBLESHOOTING',demos:'VISUAL EXPLANATIONS',manual:'COMMAND MANUAL',labs:'PRACTICE',roadmap:'LEARNING PATH','jp-library':'JAPANESE LIBRARY',anime:'LISTENING PRACTICE','hub-course':'LESSON',classroom:'LESSON','python-course':'PYTHON LESSON'};
const efStorageKey='learning-display-theme';
function efSetTheme(value){document.documentElement.dataset.theme=value;try{localStorage.setItem(efStorageKey,value);}catch{}efUpdateThemeButtons();}
function efUpdateThemeButtons(){const dark=document.documentElement.dataset.theme==='dark';document.querySelectorAll('[data-ef-theme]').forEach(b=>{b.textContent=dark?'浅色':'深色';b.setAttribute('aria-label',dark?'切换到浅色界面':'切换到深色界面');b.setAttribute('aria-pressed',String(dark));});}
const efPreviousNav=hubNav;
hubNav=function(){return efPreviousNav().replace('</header>','<button class="ef-theme-button" data-ef-theme type="button">深色</button></header>');};
hubHome=function(){
 const index=hubNextIndex('beginner'),lesson=hubCurriculum.beginner[index],total=courses.length+pythonLessons.length+Object.values(hubCurriculum).reduce((n,c)=>n+c.length,0),done=state.completed.length+Object.values(hubState.completed).reduce((n,c)=>n+c.length,0)+pythonLessons.filter((_,i)=>pythonPassed(i)).length;
 return `<main class="hub-main ef-home"><section class="ef-home-hero beginner-start"><div class="ef-home-intro"><p class="ef-eyebrow">// LEARNING ROOM</p><h1>从看懂，<br>到亲手做到。</h1><p class="ef-home-lead">先认识工具，再掌握命令。<br>把每一次练习，变成能用上的本领。</p><div class="ef-home-meta"><span><b>${total}</b> 节课程</span><span><b>${done}</b> 已完成</span><span><b>${bookCatalog.filter(b=>b.file).length}</b> 本原文书籍</span></div></div><div class="ef-current-lesson"><div class="ef-current-heading"><span>// NEXT LESSON</span><span>零基础准备</span></div><div class="ef-lesson-number">${String(index+1).padStart(2,'0')}<small>/ ${hubCurriculum.beginner.length}</small></div><h2>${esc(lesson.title)}</h2><p>看图认识，逐页理解，再亲手验证。<br>本节位置和练习结果会自动保存在本机。</p><button class="primary ef-home-start" data-hub="lesson" data-track="beginner" data-index="${index}">${hubState.completed.beginner.length?'继续零基础课程':'从这一课开始'}<span aria-hidden="true">↗</span></button><button class="text-button ef-linux-entry" data-action="lesson" data-id="${firstUnfinishedCourse()}">已认识基础概念？进入 Linux 课堂</button></div></section><section class="ef-home-route"><div class="ef-section-heading"><div><span class="ef-eyebrow">// LEARNING PATH</span><h2>把知识连成一条路</h2></div><button class="text-button" data-guide="open">第一次来？查看学习指南</button></div><ol class="ef-path-steps">${['认识电脑与终端','Linux 与常用命令','日志与网络排查','数据库与系统部署','自动化、Docker 与 K8s'].map((t,i)=>`<li><span>${String(i+1).padStart(2,'0')}</span><b>${t}</b></li>`).join('')}</ol><div class="hero-actions"><button class="secondary" data-hub="subject" data-id="ops">查看运维工作实战</button><button class="secondary" data-incident="open" data-id="schema-500">直接进入排障演练</button></div></section><section class="ef-home-subjects"><div class="ef-section-heading"><div><span class="ef-eyebrow">// CLASSROOMS</span><h2>选择你的课堂</h2></div><span class="ef-field">${Object.keys(hubSubjects).length} 个学习方向</span></div><div class="subject-grid">${Object.entries(hubSubjects).map(([id,s],i)=>`<button class="subject-card" data-hub="subject" data-id="${id}"><span class="ef-subject-index">${String(i+1).padStart(2,'0')}</span><div><small>${esc(s.tag)}</small><h2>${esc(s.name)}</h2><p>${esc(s.description)}</p></div><span class="card-link">${id==='ops'?hubCurriculum.opswork.length:id==='python'?pythonLessons.length:hubCurriculum[id].length} 节课 <span aria-hidden="true">↗</span></span></button>`).join('')}</div></section><section class="ef-home-footer"><div><span class="ef-eyebrow">// YOUR PROGRESS</span><h2>学过的，留得下来。</h2><p>本机自动记录学习位置与代码草稿。登录个人账户后，可同步学习进度、记录私人笔记。</p></div><button class="secondary" data-account="open">个人账户与笔记</button><button class="text-button" data-hub="books">去书房读一会儿</button></section></main>`;
};
function efDecorate(){
 document.body.classList.add('ef','ef-contours','endfield-learning');
 document.body.dataset.efPage=view==='hub'?'showcase':['incident','demos','labs'].includes(view)?'console':'reading';
 if(view==='hub')document.querySelector('.mobile-subject-picker')?.setAttribute('hidden','');
 const main=document.querySelector('main');
 if(main&&view!=='hub'){
  const title=main.querySelector('h1');
  if(title&&!main.querySelector('.ef-page-label')){const label=document.createElement('div');label.className='ef-eyebrow ef-page-label';label.textContent='// '+(efPageNames[view]||'LEARNING');title.before(label);}
 }
 document.querySelectorAll('.subject-card,.path-card').forEach((node,i)=>{if(!node.querySelector('.ef-list-index')&&!node.querySelector('.path-number')&&!node.querySelector('.ef-subject-index')){const n=document.createElement('span');n.className='ef-list-index';n.textContent=String(i+1).padStart(2,'0');node.prepend(n);}});
 const learningViews=['hub','subject','hub-course','classroom','python-course','roadmap'];
 document.querySelectorAll('.mobile-tabs button').forEach(b=>{const active=b.dataset.hub==='home'?learningViews.includes(view):b.dataset.hub==='books'?['books','reader'].includes(view):b.dataset.account?view==='account':!learningViews.includes(view)&&!['books','reader','account'].includes(view);if(active)b.setAttribute('aria-current','page');else b.removeAttribute('aria-current');if(b.querySelector('.ef-tab-label'))return;const en=b.dataset.hub==='home'?'LEARN':b.dataset.hub==='books'?'BOOKS':b.dataset.account?'ACCOUNT':'TOOLS';const label=document.createElement('small');label.className='ef-tab-label';label.textContent=en;b.prepend(label);});
 document.querySelectorAll('.hub-header nav button').forEach(b=>{if(b.dataset.account)b.setAttribute('aria-current',view==='account'?'page':'false');});
 efUpdateThemeButtons();
}
const efPreviousRender=render;render=function(){efPreviousRender();efDecorate();};
document.addEventListener('click',e=>{if(e.target.closest('[data-ef-theme]'))efSetTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');});
const efSystemTheme=matchMedia('(prefers-color-scheme: dark)');
efSystemTheme.addEventListener('change',e=>{try{if(localStorage.getItem(efStorageKey))return;}catch{}document.documentElement.dataset.theme=e.matches?'dark':'light';efUpdateThemeButtons();});
render();
